/** Finding artifacts to link to a release. */

export const ARTIFACTS_PER_PAGE = 5

export interface PickableArtifact {
    id: number
    name: string
    source?: string
    origin?: string | null
    run_id?: string | null
    size_bytes: number
    created_at?: string | null
    created_by?: string | null
    tags?: string[]
}

/** Generated by a run, uploaded here, or registered from a path on the server. */
export function artifactOrigin(artifact: PickableArtifact): string {
    if (artifact.run_id) return 'Generated'
    return artifact.source === 'upload' ? 'Uploaded' : 'Server path'
}

/** The database keeps UTC without saying so; a browser would otherwise read it as local time. */
export function artifactTime(value: string): string {
    return /(?:Z|[+-]\d\d:?\d\d)$/.test(value) ? value : `${value.replace(' ', 'T')}Z`
}

/** Every word must appear somewhere: its name, what made it, who, its tags or how it got here. */
export function searchArtifacts<T extends PickableArtifact>(artifacts: T[], query: string): T[] {
    const words = query.toLowerCase().split(/\s+/).filter(Boolean)
    if (!words.length) return artifacts
    return artifacts.filter((artifact) => {
        const text = [
            artifact.name,
            artifact.origin,
            artifact.created_by,
            artifactOrigin(artifact),
            ...(artifact.tags ?? []),
        ].join(' ').toLowerCase()
        return words.every((word) => text.includes(word))
    })
}

/** Newest first; artifacts without a date go last. */
export function newestFirst<T extends PickableArtifact>(artifacts: T[]): T[] {
    return [...artifacts].sort((left, right) => {
        const order = (right.created_at ?? '').localeCompare(left.created_at ?? '')
        return order || right.id - left.id
    })
}

export function artifactPage<T>(items: T[], page: number): { items: T[]; page: number; pages: number } {
    const pages = Math.max(1, Math.ceil(items.length / ARTIFACTS_PER_PAGE))
    const shown = Math.min(Math.max(1, page), pages)
    const from = (shown - 1) * ARTIFACTS_PER_PAGE
    return { items: items.slice(from, from + ARTIFACTS_PER_PAGE), page: shown, pages }
}
